-- Native isolated SQL: generic measurement, immutable history and private reporting.
begin;
set local time zone 'UTC';
create function pg_temp.check_metric(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end $$;
create function pg_temp.reject_metric(q text,label text) returns void language plpgsql as $$begin begin execute q;exception when others then return;end;raise exception 'FAIL accepted: %',label;end $$;
grant execute on function pg_temp.check_metric(boolean,text),pg_temp.reject_metric(text,text) to authenticated,service_role;
