select set_config('qa.metrics.defs','[{"key":"all","label":"Registrations","type":"event_count","event_name":"registered"},{"key":"people","label":"People","type":"unique_people","event_name":"registered"},{"key":"contexts","label":"Webinar registrations","type":"unique_per_context","event_name":"registered"},{"key":"waiting","label":"Waiting","type":"current_state","event_name":"pool_state","state_value":"waiting"},{"key":"live","label":"Live","type":"live_presence","event_name":"heartbeat"},{"key":"ratio","label":"People per registration","type":"ratio","numerator_key":"people","denominator_key":"all"},{"key":"unknown","label":"Not connected","type":"unique_people","event_name":"unconnected"}]',true);
